// Assign the holdout exactly the way core/holdout.py does.
//
// sha256 of "campaign id | customer id | seed", take the first twelve hex digits as a
// number in [0, 1), sort ascending, and hold back the lowest fifteen percent. Hashing
// rather than shuffling means a retry of this node produces the identical split, which is
// why retryOnFail on the dispatch below is safe.
//
// The backend verifies this split before it sends anything: disjoint arms, right sizes,
// every customer accounted for. If this node and core/holdout.py ever disagree, the
// response says so in matches_core_holdout rather than quietly sending the wrong thing.

const HOLDOUT_SHARE = 0.15;

const callNode = $('Phone the shopkeeper in Hindi').first().json;
const callId = callNode.call_id;
const seed = 20260919;
const customerIds = callNode.brief.evidence
  ? $('Is anything wrong at this shop').first().json.signals.lapsed_regulars.customer_ids
  : [];

async function score(customerId) {
  const text = `${callId}|${customerId}|${seed}`;
  const bytes = new TextEncoder().encode(text);
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  const hex = Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
  return parseInt(hex.slice(0, 12), 16) / Math.pow(16, 12);
}

const unique = Array.from(new Set(customerIds)).sort();
const scored = [];
for (const customerId of unique) {
  scored.push({ customerId, value: await score(customerId) });
}
scored.sort((a, b) => a.value - b.value);

const holdoutCount = Math.round(unique.length * HOLDOUT_SHARE);
const control = scored.slice(0, holdoutCount).map((row) => row.customerId).sort();
const treated = scored.slice(holdoutCount).map((row) => row.customerId).sort();

return [{
  json: {
    call_id: callId,
    merchant_id: $('Start the night for one merchant').first().json.merchant_id,
    seed,
    treated,
    control,
    treated_count: treated.length,
    holdout_count: control.length,
  },
}];
